<script setup lang="ts">
import {technicalFacts,type Product} from '@ellas/shared';
useSeo('Comparar prendas','Compara gramaje, composición y variantes reales para elegir el vestuario de tu equipo.');
const route=useRoute();const comparison=useComparison();const selectedColors=reactive<Record<string,string>>({});const differences=ref(false);const failure=ref('');
const refs=computed(()=>{const raw=typeof route.query.refs==='string'?route.query.refs:'';return [...new Set(raw.split(',').map(v=>v.trim().toUpperCase()).filter(v=>/^[A-Z0-9]{2,50}$/.test(v)))].slice(0,3);});
const {data,error}=await useFetch<{products:Product[];ranking:{reference:string;orders:number;units:number}[]}>('/api/catalog/comparison',{query:{refs:computed(()=>refs.value.join(','))}});
const products=computed(()=>data.value?.products||[]);
onMounted(()=>{if(refs.value.length)comparison.references=[...refs.value];else if(comparison.references.length)void navigateTo({path:'/comparar',query:{refs:comparison.references.join(',')}},{replace:true});});
watch(refs,value=>{comparison.references=[...value];});
function select(product:Product){failure.value='';if(refs.value.includes(product.reference))return;if(refs.value.length>=3){failure.value='Quita una prenda antes de añadir una cuarta.';return;}void navigateTo({path:'/comparar',query:{refs:[...refs.value,product.reference].join(',')}});}
function remove(ref:string){void navigateTo({path:'/comparar',query:{refs:refs.value.filter(r=>r!==ref).join(',')}});}
const rows=computed(()=>{const definitions:[string,(p:Product)=>string][]=[['Gramaje',p=>{const fact=technicalFacts(p).weight;return fact?fact.source+' g/m²':'No especificado';}],['Composición',p=>technicalFacts(p,selectedColors[p.reference]).composition],['Matices del tejido',p=>{const facts=technicalFacts(p,selectedColors[p.reference]);return (!facts.compositionResolved?'Consulta las excepciones de color. ':'')+facts.exceptions.join(' · ')||'Sin excepciones indicadas';}],['Tipo de prenda',p=>p.category],['Colección',p=>p.collection],['Para quién',p=>p.audience],['Detalles de la ficha',p=>p.description],['Tallas',p=>(selectedColors[p.reference]?p.colors.find(c=>c.code===selectedColors[p.reference])?.sizes:p.sizes)?.join(' · ')||'Consultar ficha'],['Colores',p=>String(p.colors.length)+' opciones'],['Más pedidos · 90 días',p=>{const rank=data.value?.ranking.find(r=>r.reference===p.reference);return rank?rank.orders+' pedidos · '+rank.units+' prendas':'Sin historial real suficiente';}]];return definitions.map(([name,value])=>({name,values:products.value.map(value)})).filter(row=>!differences.value||new Set(row.values).size>1);});
</script>
<template><div class="container compare-page"><div class="breadcrumb"><NuxtLink to="/">Inicio</NuxtLink><span>/</span><span>Comparar prendas</span></div><header class="compare-heading"><span class="eyebrow">ELIGE CON LAS COSAS CLARAS</span><h1>Encuentra la que<br/><span class="serif-word">encaja contigo.</span></h1><p>Tejido, gramaje y detalles reales. Lo importante, a la vista.</p></header><div class="compare-search"><ProductSearch id="compare-search" label="Añade hasta tres prendas para comparar" @select="select"/></div><p v-if="failure||error" class="alert error" role="alert">{{failure||'No se ha podido cargar la comparación.'}}</p><div v-if="products.length" class="compare-controls"><label class="checkbox-row"><input v-model="differences" type="checkbox"/>Solo diferencias</label><span class="fine-print">Desliza la tabla para ver todas las prendas en móvil.</span></div><div v-if="products.length" class="compare-scroll"><table class="comparison-table"><caption class="sr-only">Comparación técnica de prendas</caption><thead><tr><th scope="col">Lo que necesitas saber</th><th v-for="p in products" :key="p.reference" scope="col"><button class="compare-remove" :aria-label="`Quitar ${p.reference}`" @click="remove(p.reference)"><AppIcon name="X" :size="16"/></button><img :src="p.imageSmall" :alt="p.name" width="180" height="225"/><small>{{p.reference}}</small><h2>{{p.name}}</h2><label>Composición según color<select v-model="selectedColors[p.reference]"><option :value="undefined">Base y excepciones</option><option v-for="c in p.colors" :key="c.code" :value="c.code">{{c.name}} · {{c.code}}</option></select></label><NuxtLink :to="{path:'/hacer-pedido',query:{ref:p.reference}}" class="button dark">Elegir esta prenda <AppIcon name="ArrowRight" :size="16"/></NuxtLink></th></tr></thead><tbody><tr v-for="row in rows" :key="row.name"><th scope="row">{{row.name}}</th><td v-for="(value,i) in row.values" :key="i">{{value}}</td></tr><tr><th scope="row">Fuente y medidas</th><td v-for="p in products" :key="p.reference"><NuxtLink :to="`/catalogo/${p.slug}`" class="text-link">Ver ficha · p. {{p.source.printedPages}} <AppIcon name="ArrowUpRight" :size="15"/></NuxtLink></td></tr></tbody></table></div><div v-else class="order-start"><AppIcon name="SlidersHorizontal" :size="40"/><h2>Dos prendas. Una decisión más fácil.</h2><p>Busca arriba o elige «Comparar» desde cualquier prenda del catálogo.</p><NuxtLink to="/catalogo" class="button outline">Explorar catálogo <AppIcon name="ArrowRight"/></NuxtLink></div><p v-if="new Set(products.map(p=>p.category)).size>1" class="alert">Estás comparando tipos de prenda diferentes. Sus características responden a usos distintos.</p><p class="compare-explanation">Un gramaje mayor no significa mejor calidad. Elige según el uso y el tejido. Los colores y tallas del catálogo no indican stock.</p></div></template>
